<?php require __DIR__.'/../_dashboard_start.php'; $uid=$user['id'];
$s=$pdo->prepare('SELECT COUNT(*) FROM modules WHERE teacher_id=?');$s->execute([$uid]);$mods=(int)$s->fetchColumn();
$s=$pdo->prepare('SELECT COUNT(*) FROM tasks t JOIN modules m ON m.id=t.module_id WHERE m.teacher_id=?');$s->execute([$uid]);$tasks=(int)$s->fetchColumn();
$s=$pdo->prepare('SELECT COUNT(*) FROM submissions s JOIN tasks t ON t.id=s.task_id JOIN modules m ON m.id=t.module_id WHERE m.teacher_id=? AND s.score IS NULL');$s->execute([$uid]);$pending=(int)$s->fetchColumn();
$s=$pdo->prepare('SELECT COUNT(DISTINCT u.id) FROM users u JOIN classes c ON c.name=u.class_name JOIN teacher_assignments a ON a.class_id=c.id WHERE a.teacher_id=? AND u.role="siswa"');$s->execute([$uid]);$students=(int)$s->fetchColumn();
$recent=$pdo->prepare('SELECT s.id,s.submitted_at,t.title task_title,u.name student_name,m.title module_title FROM submissions s JOIN tasks t ON t.id=s.task_id JOIN modules m ON m.id=t.module_id JOIN users u ON u.id=s.student_id WHERE m.teacher_id=? ORDER BY s.submitted_at DESC LIMIT 8');$recent->execute([$uid]);$rows=$recent->fetchAll();
?>
<div class="page-heading"><div><span class="eyebrow">RUANG KERJA PENGAJAR</span><h1>Dashboard Guru</h1><p>Berikut ringkasan aktivitas pembelajaran Anda.</p></div><a class="btn btn-primary" href="<?= e(url('tasks')) ?>"><i class="fa-solid fa-plus"></i> Buat Tugas</a></div>
<div class="stats-grid"><article class="stat-card"><div class="stat-icon blue"><i class="fa-solid fa-book-open"></i></div><div><span>Modul Diampu</span><strong><?= $mods ?></strong><small>Modul aktif</small></div></article><article class="stat-card"><div class="stat-icon orange"><i class="fa-solid fa-clipboard-check"></i></div><div><span>Tugas Dibuat</span><strong><?= $tasks ?></strong><small>Seluruh tugas</small></div></article><article class="stat-card"><div class="stat-icon green"><i class="fa-solid fa-users"></i></div><div><span>Total Siswa</span><strong><?= $students ?></strong><small>Kelas yang ditugaskan</small></div></article><article class="stat-card"><div class="stat-icon purple"><i class="fa-solid fa-marker"></i></div><div><span>Perlu Dinilai</span><strong><?= $pending ?></strong><small>Pengumpulan baru</small></div></article></div>
<section class="panel"><div class="panel-head"><h3>Pengumpulan Tugas Terbaru</h3><a href="<?= e(url('submissions')) ?>">Lihat semua</a></div><?php if(!$rows): ?><div class="empty-state">Belum ada pengumpulan tugas.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Siswa</th><th>Tugas</th><th>Modul</th><th>Waktu</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['student_name']) ?></td><td><?= e($r['task_title']) ?></td><td><?= e($r['module_title']) ?></td><td><?= e(format_date($r['submitted_at'])) ?></td><td><span class="badge <?= $r['score']===null?'warning':'success' ?>"><?= $r['score']===null?'Pending':'Dinilai' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__.'/../_dashboard_end.php'; ?>